        for c0 in range(0, w, 5):
            block = tuple(
                tuple(grid[r][c] for c in range(c0, min(c0 + 4, w)))
                for r in range(r0, min(r0 + 4, h))
            )
            if any(v == 2 for row in block for v in row):
                patterns.setdefault(block, []).append((r0, c0))

    # For each block, use the most frequent pattern as a template and
    # color the discrepant 2 in the minority pattern.
    counts = {}
    for b in patterns:
        counts[b] = sum(len(pos) for bb, pos in patterns.items() if bb == b)

    if patterns:
        template = max(patterns, key=lambda b: len(patterns[b]))
        for block, positions in patterns.items():
            if block == template:
                continue
            for r0, c0 in positions:
                for i, row in enumerate(block):
                    for j, v in enumerate(row):
                        if v == 2 and (i >= len(template) or j >= len(template[i]) or template[i][j] != 2):
                            out[r0 + i][c0 + j] = 8

    return out
